// Home.js
import React from 'react';
import { Carousel } from 'react-responsive-carousel';
import 'react-responsive-carousel/lib/styles/carousel.min.css';
import homeImage from './images/home.jpg';
import project1Image from './images/project1.jpg';
import project2Image from './images/project2.jpg';
import linkedinIcon from './images/linkedin.png';
import githubIcon from './images/github.png';

const projects = [
  {
    title: 'Sign Bridge',
    image: project1Image,
    description: `Implemented an interactive American Sign Language learning web application where users utilize a webcam to demonstrate sign language and receive real-time feedback. Trained a Sign Language Recognition model with CNN using Pytorch, Numpy, Tensorflow, Mediapipe.`,
  },
  {
    title: 'UTimetable',
    image: project2Image,
    description: `Developed a Java-based application enabling users to create accounts, manage timetables, and find overlapping free time slots using advanced algorithms.`,
  },
];

const Home = () => {
  return (
    <main className="main-content">
      <div className="image-container">
        <img className="home-image" src={homeImage} alt="Home" />
      </div>

      <div className="box">
        Hi! I'm Narae, a former/aspiring AI Engineer passionate about leveraging AI and full-stack development to create ethical software solutions improving accessibility.
      </div>

      <section className="recent-projects">
        <h2>Recent Projects</h2>
        <Carousel autoPlay infiniteLoop showThumbs={false} showStatus={false}>
          {projects.map((project, i) => (
            <div className="project-container" key={i}>
              <img className="project-image" src={project.image} alt={project.title} />
              <h3 className="project-title">{project.title}</h3>
              <p className="project-description">{project.description}</p>
            </div>
          ))}
        </Carousel>
      </section>

      <section className="contact-section">
        <p>Contact me at: <a href="mailto:narae828@hotmail.com">narae828@hotmail.com</a></p>
        <div className="social-media">
          <a href="https://www.linkedin.com/in/narae-lee-a3390721b/" target="_blank" rel="noopener noreferrer">
            <img src={linkedinIcon} alt="LinkedIn" />
          </a>
          <a href="https://github.com/naraeleee" target="_blank" rel="noopener noreferrer">
            <img src={githubIcon} alt="GitHub" />
          </a>
        </div>
      </section>

      <footer className="footer">
        <p>&copy; {new Date().getFullYear()} Narae Lee. All rights reserved.</p>
      </footer>
    </main>
  );
};

export default Home;
